config.code:
const list = String(inputs.urls || '')
  .split(/\r?\n/)
  .map((s) => s.trim())
  .filter((s) => /^https?:\/\//i.test(s))
const n = typeof inputs.max === 'number' ? inputs.max : parseInt(inputs.max, 10)
const limit = Number.isFinite(n) && n > 0 ? n : 8
return { list: list.slice(0, limit), found: list.length }

const text = String(inputs.text || '')
// 少于 300 字视为抓取失败/非正文页，不入资产也不进蒸馏
if (text.length < 300) return { ok: false, title: '', text: '' }
const title = String(inputs.title || '').trim() || '文章' + (Number(inputs.index) + 1)
return { ok: true, title, text }

const items = Array.isArray(inputs.items) ? inputs.items : []
// loop 回边收集的是各迭代 loop-back 源节点的完整输出——code 节点形状为 { result: ... }，先解包
const unwrap = (x) => (x && x.result && typeof x.result === 'object') ? x.result : x
const okItems = items.map(unwrap).filter((x) => x && x.ok && x.text)
const digest = okItems.map((x, i) => '【文章' + (i + 1) + '】' + (x.title || '') + '\n' + String(x.text).slice(0, 1200)).join('\n\n')
const fullText = okItems.map((x) => '<<<文章：' + (x.title || '') + '>>>\n' + x.text).join('\n\n')
return { digest, fullText, count: okItems.length, total: items.length }

